<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-3"><h2 class="h5"><?= esc($title) ?></h2><a href="/purchase-orders" class="btn btn-light">Kembali</a></div><form method="post" action="<?= esc($action) ?>" class="card"><div class="card-body row g-3"><?= csrf_field() ?><div class="col-md-4"><label class="form-label">Vendor *</label><select name="vendor_id" required class="form-select"><option value="">Pilih vendor</option><?php foreach($vendors as $v): ?><option value="<?= $v['id'] ?>" <?= ($po['vendor_id']??'')==$v['id']?'selected':'' ?>><?= esc($v['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Nomor PO *</label><input name="po_no" required class="form-control" value="<?= esc($po['po_no']??'PO-'.date('YmdHis')) ?>"></div><div class="col-md-2"><label class="form-label">Tanggal</label><input type="date" name="po_date" class="form-control" value="<?= esc($po['po_date']??date('Y-m-d')) ?>"></div><div class="col-md-2"><label class="form-label">Status</label><select name="status" class="form-select"><option value="draft">Draft</option><option value="sent" <?= ($po['status']??'')==='sent'?'selected':'' ?>>Dikirim</option><option value="approved" <?= ($po['status']??'')==='approved'?'selected':'' ?>>Disetujui</option></select></div><div class="col-12"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Nama Produk</th><th>Qty</th><th>Satuan</th><th>Harga</th></tr></thead><tbody><?php $items=$po['items']??[[]];foreach($items as $i=>$item): ?><tr><td><input name="items[<?= $i ?>][product_name]" class="form-control" value="<?= esc($item['product_name']??'') ?>"></td><td><input type="number" step="0.01" min="0.01" name="items[<?= $i ?>][quantity]" class="form-control" value="<?= esc($item['quantity']??1) ?>"></td><td><input name="items[<?= $i ?>][unit]" class="form-control" value="<?= esc($item['unit']??'pcs') ?>"></td><td><input type="number" step="0.01" min="0" name="items[<?= $i ?>][unit_price]" class="form-control" value="<?= esc($item['unit_price']??0) ?>"></td></tr><?php endforeach; ?></tbody></table></div><div class="form-text">Tambahkan baris item melalui edit form jika diperlukan.</div></div><div class="col-md-3"><label class="form-label">Pajak (%)</label><input type="number" step="0.01" name="tax_percent" class="form-control" value="<?= esc($po['tax_percent']??0) ?>"></div><div class="col-12"><label class="form-label">Catatan</label><textarea name="notes" class="form-control"><?= esc($po['notes']??'') ?></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Simpan PO</button></div></form><?= $this->endSection() ?>
